  + Date : date
}

class Appointment {
  + ConfirmationNumber : string
  + Date : date
  + StartTime : time
  + EndTime : time
}

class BusinessHour {
  + StartTime : time
  + EndTime : time
}

class Lab {
  + Address : string
  + RegistrationNumber : string
  + ChangeCancelFee : float
}

class Test {
  + Name : string
  + Duration : string
}

class TestType {
  + Name : string
  + Access : AccessType
}

