Patient "1" -- "*" TestResult : views
Requisition "1" -- "*" SpecificTest : contains
SpecificTest "1" -- "0..1" TestResult : has
Patient "1" -- "*" Appointment : makes
Appointment "1" -- "1" Requisition : for
Appointment "*" -- "1" Lab : at
